-- 申报评审可追溯性：版本快照、评审意见和未获资助复盘。
BEGIN;

CREATE TABLE IF NOT EXISTS "纵向项目申报版本" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "纵向项目申报编号" integer NOT NULL,
    "版本号" integer NOT NULL,
    "快照" jsonb NOT NULL,
    "变更类型" varchar(20) NOT NULL,
    "变更人编号" integer,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_纵向项目申报版本" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_纵向项目申报版本" UNIQUE ("纵向项目申报编号", "版本号")
);

CREATE INDEX IF NOT EXISTS "ix_纵向项目申报版本_申报"
    ON "纵向项目申报版本" ("纵向项目申报编号", "版本号" DESC);

CREATE TABLE IF NOT EXISTS "项目评审意见" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "步骤编号" integer,
    "评审人编号" integer NOT NULL,
    "意见类型" varchar(30) NOT NULL,
    "意见内容" varchar(4000) NOT NULL,
    "是否公开给申请人" boolean NOT NULL DEFAULT TRUE,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_项目评审意见" PRIMARY KEY ("编号")
);

CREATE INDEX IF NOT EXISTS "ix_项目评审意见_项目"
    ON "项目评审意见" ("流程模板编号", "项目编号", "建立时间" DESC);

CREATE TABLE IF NOT EXISTS "未获资助复盘" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "纵向项目申报编号" integer NOT NULL,
    "原因分类" varchar(50) NOT NULL,
    "复盘结论" varchar(4000) NOT NULL,
    "改进措施" varchar(4000),
    "负责人编号" integer,
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_未获资助复盘" PRIMARY KEY ("编号")
);

CREATE INDEX IF NOT EXISTS "ix_未获资助复盘_申报"
    ON "未获资助复盘" ("纵向项目申报编号", "建立时间" DESC);

CREATE OR REPLACE FUNCTION "trg_纵向项目申报版本"()
RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    next_version integer;
BEGIN
    PERFORM pg_advisory_xact_lock(4400000000::bigint + NEW."编号"::bigint);
    SELECT COALESCE(MAX("版本号"), 0) + 1
      INTO next_version
      FROM "纵向项目申报版本"
     WHERE "纵向项目申报编号" = NEW."编号";

    INSERT INTO "纵向项目申报版本" (
        "纵向项目申报编号", "版本号", "快照", "变更类型", "变更人编号"
    ) VALUES (
        NEW."编号", next_version,
        jsonb_build_object(
            '编号', NEW."编号", '分类', NEW."分类", '项目名称', NEW."项目名称",
            '申报人编号', NEW."申报人编号", '申报年度', NEW."申报年度",
            '项目类型', NEW."项目类型", '项目级别', NEW."项目级别",
            '项目来源单位', NEW."项目来源单位", '项目类别', NEW."项目类别",
            '申请经费', NEW."申请经费", '计划开始日期', NEW."计划开始日期",
            '计划完成日期', NEW."计划完成日期", '项目摘要', NEW."项目摘要",
            '是否需要伦理评审', NEW."是否需要伦理评审", '是否需要伦理批文', NEW."是否需要伦理批文",
            '伦理批文编号', NEW."伦理批文编号", '伦理批文路径', NEW."伦理批文路径",
            '项目申报书路径', NEW."项目申报书路径", '是否立项', NEW."是否立项",
            '备注', NEW."备注"
        ),
        TG_OP, NEW."申报人编号"
    );
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS "trg_纵向项目申报版本" ON "纵向项目申报";
CREATE TRIGGER "trg_纵向项目申报版本"
AFTER INSERT OR UPDATE ON "纵向项目申报"
FOR EACH ROW EXECUTE FUNCTION "trg_纵向项目申报版本"();

-- 为已有申报建立不可变的迁移基线，后续修改由触发器继续追加版本。
INSERT INTO "纵向项目申报版本" (
    "纵向项目申报编号", "版本号", "快照", "变更类型", "变更人编号"
)
SELECT y."编号", 1,
       jsonb_build_object(
           '编号', y."编号", '分类', y."分类", '项目名称', y."项目名称",
           '申报人编号', y."申报人编号", '申报年度', y."申报年度",
           '项目类型', y."项目类型", '项目级别', y."项目级别",
           '项目来源单位', y."项目来源单位", '项目类别', y."项目类别",
           '申请经费', y."申请经费", '计划开始日期', y."计划开始日期",
           '计划完成日期', y."计划完成日期", '项目摘要', y."项目摘要",
           '是否需要伦理评审', y."是否需要伦理评审", '是否需要伦理批文', y."是否需要伦理批文",
           '伦理批文编号', y."伦理批文编号", '伦理批文路径', y."伦理批文路径",
           '项目申报书路径', y."项目申报书路径", '是否立项', y."是否立项",
           '备注', y."备注"
       ),
       '迁移基线', y."申报人编号"
  FROM "纵向项目申报" y
 WHERE NOT EXISTS (
       SELECT 1 FROM "纵向项目申报版本" v
        WHERE v."纵向项目申报编号" = y."编号"
          AND v."版本号" = 1
  );

UPDATE "系统迁移版本"
   SET "版本" = 44,
       "脚本" = '001-044',
       "检查摘要" = '增加申报版本快照、评审意见汇总和未获资助复盘记录'
 WHERE "编号" = 1;

COMMIT;
